{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Octreotide, a cyclic octapeptide, has an absolute oral bioavailability of only 0.6 ± 0.4% in healthy humans; the query is a much larger peptide with multiple amide bonds and a fatty-acid/PEG modification, so the same oral absorption barriers apply.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Plecanatide, a peptide, shows negligible systemic availability after oral administration in humans, supporting very low oral bioavailability for peptide-based drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "GHRP-6, a small peptide, has <1% oral bioavailability in humans; the query is larger and more complex, making high oral bioavailability unlikely.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Hexarelin, a peptidomimetic, has oral bioavailability of 0.3 ± 0.1% in humans, far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Enalkiren, a peptidomimetic renin inhibitor, has 0.5% oral bioavailability in humans, illustrating the poor oral absorption typical of peptide-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "CGP 38560, a peptide-like renin inhibitor, has <1% oral bioavailability in humans at 200 mg p.o., supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Macimorelin, a small peptidomimetic, has good oral bioavailability, but it is much smaller and less peptide-like than the query; this high-F example has limited transferability to the large fatty-acid/PEG-modified peptide.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large, highly functionalized peptide with a fatty-acid/PEG side chain. Multiple human peptide/peptidomimetic drugs (octreotide, GHRP-6, hexarelin, enalkiren, plecanatide, CGP 38560) show oral bioavailability below 1-2%, far below the 20% threshold. The only high-F analogue is a small non-peptide or small peptidomimetic with low transferability. Therefore, the query is predicted to have low absolute oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule.",
    "No experimental data on the specific fatty-acid/PEG modification's effect on oral absorption.",
    "Most evidence comes from other peptides/peptidomimetics with different sequences, sizes, and formulations.",
    "No data on whether an absorption-enhancing formulation would be used."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

